import{_ as e,o as s,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"地球科学","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/index.md","filePath":"topics/earth-science/index.md"}'),i={name:"topics/earth-science/index.md"};function o(a,t,c,g,h,l){return s(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="地球科学" tabindex="-1">地球科学 <a class="header-anchor" href="#地球科学" aria-label="Permalink to &quot;地球科学&quot;">​</a></h1><blockquote><p>地震、行星、真菌网络——地球系统的深层结构</p></blockquote><h2 id="文件列表" tabindex="-1">文件列表 <a class="header-anchor" href="#文件列表" aria-label="Permalink to &quot;文件列表&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-28-earth.html">科学日报 2026-10-28（环境/稻田抗生素—甲基汞）</a> — 第47期科学板块（1 篇）：中国主要稻区 <strong>40 份稻田土</strong>加 <strong>10 mg/kg 氟喹诺酮（FQ）<strong>培养 21 天，<strong>甲基汞（MeHg，神经毒性）升高 2.9%–19.7%</strong>；代谢抑制/微宇宙实验表明来自</strong>被刺激的微生物汞甲基化</strong>（非去甲基化受抑），<strong>SRB 主导</strong>（抑硫酸盐还原使诱导甲基化降 <strong>31%–75%</strong>）；宏基因组锁定<strong>携 hgcA 的 SRB</strong> 为关键甲基化者——FQ <strong>选择性压制竞争菌群、扶持耐受抗生素且代谢活跃的 SRB</strong>（尤其<strong>还原性乙酰辅酶 A 途径</strong>），<strong>在不显著改变丰度/群落结构下抬高甲基化活性</strong> → <strong>丰度不变活性升高＝效果藏在代谢状态；抗生素代价不止耐药性，还顺元素循环放大毒物暴露</strong>（Nature Communications, 10.1038/s41467-026-79083-7）｜亦见 <code>topics/biomedicine/index.md</code></li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-27-earth.html">科学日报 2026-10-27（北极海洋/初级生产力）</a> — 第46期科学板块：<strong>巴伦支海硝酸盐受限冰区</strong> 卫星水色 <strong>1998–2023</strong> 追踪——<strong>春季（4–5 月）初级生产力下降 45%</strong>（每十年 <strong>−90.43 mg C m⁻² day⁻¹, p&lt;0.05</strong>），驱动是<strong>春季硝酸盐可利用性下降</strong>（冬季补给变慢 + 上游消耗 + <strong>大西洋化</strong>净输出）叠加<strong>大气波列 + 淡水减少 → 混合层加深 → 光照下降</strong> → <strong>「年总量上升 + 春季崩塌」的聚合掩盖</strong>、北极食物网级联风险（Nature Communications, 10.1038/s41467-026-79272-4）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-25-earth.html">科学日报 2026-10-25（古气候/劳伦泰德冰盖）</a> — 第44期科学板块：更新世最大冰盖<strong>劳伦泰德冰盖（LIS）<strong>的最后残骸=加拿大</strong>巴芬岛 Barnes 冰帽</strong>——约 <strong>3600 年前</strong>达间冰期<strong>最小规模</strong>、约 <strong>2000 年前开始再扩张</strong>（<strong>再扩张标志下一次冰期开始</strong>）、新生 LIS 约 <strong>1960 年</strong>达最大规模，此后<strong>人为夏季升温</strong>使<strong>质量平衡转负、冰缘退缩</strong>→ <strong>下一次冰期被终止</strong>；在<strong>夏季日照持续下降</strong>的背景下冰期却被终结 → <strong>恰好说明异常温室气体强迫之大</strong>；<strong>用系统内部参照系（轨道时钟）判定人为改写</strong>（Science, 10.1126/science.aed3379）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-22-earth.html">科学日报 2026-10-22（海岸带/防灾）</a> — 第41期科学板块：把<strong>完整盐沼原状</strong>搬进世界最大<strong>波浪水槽</strong>、波高加到 <strong>2 m 有效波高</strong>——<strong>滩面基质侵蚀可忽略</strong>，但<strong>植被被逐步破坏、消浪能力随之下降</strong>；消浪只在<strong>低能海岸（≤1 m）&gt;10%（最高约 50%）</strong>，<strong>高能海岸（&gt;1 m）&lt;10%</strong>（Nature, 10.1038/s41586-026-11145-8）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-21-earth.html">科学日报 2026-10-21（地球/行星）</a> — 第40期科学板块两篇：①全球 <strong>3,806 个城市群</strong>两年十年卫星+4,855 气象站评估 → 全球北方<strong>降温饱和/回报递减</strong>、全球南方<strong>植被停滞或流失</strong>，绿化不足以抵消变暖（<strong>气候公平裂缝</strong>；PNAS, 10.1073/pnas.2616535123）；②<strong>MAVEN × 天问一号</strong>双航天器显示喷流<strong>遍布整个火星磁鞘</strong>（对比地球局限于准平行激波区），源于火星<strong>延展氢日冕</strong>的拾取离子驱动质子回旋波——对任何有延展外逸层天体通用（PNAS, 10.1073/pnas.2616582123）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-20.html">科学日报 2026-10-20</a> — 第39期科学板块：激光测高 15,330 个冰崖给出的经验约束——高崖崩解<strong>快于</strong>参数化假设（模型可能低估亚年尺度崩解速率），但<strong>动态减薄 + 退入低冰厚梯度区</strong>阻止失控后退；不稳定性潜力敏感依赖崖高之外的量（Science, 10.1126/science.aee0658）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-12.html">科学日报 2026-10-12：澳洲山火的前传 / ¹⁵N¹⁵N 称量固氮流失</a> — 东南澳千年湖相沉积显示殖民中断原住民「文化性用火」把低可燃疏林变成致密易燃林，为今日气候山火埋结构性隐患（Nature, 10.1038/s41586-026-11097-z）；用 N₂ 罕见 ¹⁵N¹⁵N 同位素体（反硝化≈0‰ vs 大气≈19‰）直接约束含水层/湖泊/缺氧区/海洋沉积物的固氮流失（Science, 10.1126/science.aei0940）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-11.html">科学日报 2026-10-11：陨石有机质记录太阳系原始氧储库</a> — 碳质球粒陨石不溶有机质（IOM）高精度三氧同位素聚在 CCAM 线附近，示原始来源氧且几乎未经母体改造（Science, 10.1073/pnas.2605307123）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-10-10.html">科学日报 2026-10-10：基拉韦厄持续一年多的间歇熔岩喷泉</a> — 2024-12 起 54 次喷泉幕（每次数小时、间隔数天-数周），多参数记录检验岩浆房压力/通道渗透率/挥发分出溶对喷发起始的控制（Science, 10.1126/science.aef2931）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-09-22.html">科学日报 2026-09-22：核试验多年后复活断层 / 保护森林比恢复划算</a> — 万塔山 17 年波形显示浅部断层延迟复活（Science, 10.1126/science.adx5917）；亚马逊前沿保护&gt;恢复、组合干预最优（Science, 10.1126/science.adx9928）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-09-21.html">科学日报 2026-09-21：LGM 甲烷寿命与氯化学</a> — 沙尘介导氯自由基使冰期甲烷寿命缩短约 20%（Science, 10.1126/science.aec4071）</li><li><a href="/zhishiku-reading/topics/earth-science/science-daily-2026-09-16.html">科学日报 2026-09-16：重思海底热泉与生命起源</a> — 对&quot;碱性热泉假说&quot;质子梯度前提的修正（PNAS, 10.1073/pnas.2613108123）</li><li><a href="/zhishiku-reading/topics/earth-science/2026-q3.html">2026 Q3</a> — 日本地震黏土层（晚了13年）、月球检疫（不可逆预防）、真菌超级网络（1.1亿亿公里）</li></ul>',4)])])}const p=e(i,[["render",o]]);export{m as __pageData,p as default};
